/* EnergyUtils anti-analysis gate — hardened build v3.
   Три нативных слоя (все статически слинкованы, на чужих ПК ничего ставить
   не надо):
     1. hb_guard.dll (Rust)      — отладчики + блэклист процессов/окон.
        Маркеры XOR-зашифрованы внутри DLL, в JS их НЕТ.
     2. hb_vm.dll (C, MinGW)     — детект виртуалок (мягкий контур).
     3. eu-guard.dll (C#)        — резервные IsDebuggerPresent/Remote/NtGlobalFlag.
   Все DLL вшиты сюда XOR+base64, в рантайме расшифровываются в %TEMP%.
   Контуры деградируют мягко: падение одного не роняет остальные. */

import { spawn, spawnSync } from "node:child_process";
import { writeFileSync, mkdirSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

// Linux: нативных DLL нет, PowerShell нет — гейт слабый (только процессы через ps).
const IS_WIN = process.platform === "win32";

// --- XOR-ключ для блобов (арифметика, в тексте его нет) -----------------
const _kA = 0x56, _kB = 0x23, _kC = 0x11;
const __KEY = _kA ^ _kB ^ _kC ^ 0x4B; // 0x2F

// --- Встроенные нативные библиотеки (base64, XOR-0x2F) -------------------
const HB_GUARD_B64 =
  "";
const HB_VM_B64 =
  "";
const GUARD_B64 =
  "";

function writeXor(b64, outPath) {
  try {
    const raw = Buffer.from(b64, "base64");
    const out = Buffer.alloc(raw.length);
    for (let i = 0; i < raw.length; i++) out[i] = raw[i] ^ __KEY;
    writeFileSync(outPath, out);
  } catch {}
  return existsSync(outPath);
}

function ensureNative() {
  const dir = join(tmpdir(), "eu-guard");
  try { mkdirSync(dir, { recursive: true }); } catch {}
  const rustP = join(dir, "hb_guard.dll");
  const cvmP = join(dir, "hb_vm.dll");
  const csP = join(dir, "eu-guard.dll");
  return {
    rust: writeXor(HB_GUARD_B64, rustP) ? rustP : null,
    cvm: writeXor(HB_VM_B64, cvmP) ? cvmP : null,
    csharp: writeXor(GUARD_B64, csP) ? csP : null,
  };
}

function csPathLit(p) {
  if (!p) return '"missing"';
  return '"' + p.replace(/\\/g, "\\\\") + '"';
}

// PS генерирует C#-обёртки с ФИКСИРОВАННЫМИ именами классов (каждый запуск —
// свежий процесс PowerShell, конфликтов типов нет) и вызывает простые
// статические методы, вся тяжёлая логика внутри C#.
function buildPsScript(paths) {
  const rustLit = csPathLit(paths.rust);
  const cvmLit = csPathLit(paths.cvm);
  const csharpLit = csPathLit(paths.csharp);
  return `
$ErrorActionPreference='SilentlyContinue'
$result = @()

# 1) Rust-ядро
if (Test-Path '${psQuote(paths.rust)}') {
  Add-Type -TypeDefinition @"
using System;
using System.Text;
using System.Runtime.InteropServices;

public static class HbRust {
    [DllImport(${rustLit}, CallingConvention = CallingConvention.Cdecl)]
    static extern int hb_scan(byte[] buf, int cap);
    [DllImport(${rustLit}, CallingConvention = CallingConvention.Cdecl)]
    static extern uint hb_version();
    public static string Run() {
        byte[] buf = new byte[65536];
        int n = hb_scan(buf, buf.Length);
        if (n <= 0) return "";
        return Encoding.ASCII.GetString(buf, 0, buf.Length).TrimEnd('\\0', ' ', '\\n', '\\r');
    }
}
"@
  $r = [HbRust]::Run()
  if ($r) { $r -split "\\n" | ForEach-Object { $s = $_.Trim(); if ($s) { $result += $s } } }
}

# 2) C-хелпер (VM, мягкий)
if (Test-Path '${psQuote(paths.cvm)}') {
  Add-Type -TypeDefinition @"
using System;
using System.Text;
using System.Runtime.InteropServices;

public static class HbVm {
    [DllImport(${cvmLit}, CallingConvention = CallingConvention.Cdecl)]
    static extern int hb_vm_scan(byte[] buf, int cap);
    public static string Run() {
        byte[] buf = new byte[65536];
        int n = hb_vm_scan(buf, buf.Length);
        if (n <= 0) return "";
        return Encoding.ASCII.GetString(buf, 0, buf.Length).TrimEnd('\\0', ' ', '\\n', '\\r');
    }
}
"@
  $v = [HbVm]::Run()
  if ($v) { $v -split "\\n" | ForEach-Object { $s = $_.Trim(); if ($s) { $result += ('~~' + $s) } } }
}

# 3) C#-резерв
if (Test-Path '${psQuote(paths.csharp)}') {
  try {
    Add-Type -Path '${psQuote(paths.csharp)}' | Out-Null
    if ([EnergyUtilsGuard.Guard]::IsDebuggerPresent()) { $result += 'dbg:cs-isdebuggerpresent' }
    $par = (Get-CimInstance Win32_Process -Filter "ProcessId=$PID").ParentProcessId
    $p = Get-Process -Id $par -ErrorAction SilentlyContinue
    if ($p) {
      $d = $false
      if ([EnergyUtilsGuard.Guard]::CheckRemoteDebuggerPresent($p.Handle, [ref]$d) -and $d) { $result += 'dbg:cs-remote' }
    }
    $gf = $false; $flag = [EnergyUtilsGuard.Guard]::GetNtGlobalFlag($par, [ref]$gf)
    if ($gf -and ($flag -band 0x70)) { $result += 'dbg:cs-ntglobalflag' }
  } catch {}
}

$result | Sort-Object -Unique
`.trim();
}

function psQuote(s) {
  return String(s).replace(/'/g, "''");
}

function parseOutput(stdout) {
  const lines = (stdout || "").split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
  const hard = [];
  const soft = [];
  for (const l of lines) {
    if (l.startsWith("~~")) soft.push(l.slice(2));
    else hard.push(l);
  }
  return { hits: [...new Set(hard)], soft: [...new Set(soft)] };
}

function runPowerShell(timeoutMs = 15000) {
  return new Promise((resolve) => {
    let out = "";
    let done = false;
    const finish = (ok) => { if (!done) { done = true; resolve({ ok, stdout: out }); } };
    let p;
    try {
      const paths = ensureNative();
      p = spawn("powershell.exe",
        ["-NoProfile", "-NonInteractive", "-ExecutionPolicy", "Bypass", "-Command", buildPsScript(paths)],
        { windowsHide: true });
    } catch { return finish(false); }
    const timer = setTimeout(() => { try { p.kill(); } catch {} finish(false); }, timeoutMs);
    p.stdout.on("data", (d) => { out += d; });
    p.on("error", () => { clearTimeout(timer); finish(false); });
    p.on("close", () => { clearTimeout(timer); finish(true); });
  });
}

// Кэш: PS-скан с Add-Type дорогой (5-15 сек). Результат живёт TTL, чтобы
// клики «Запуск» отвечали мгновенно; фоновый watchdog продлевает кэш.
let _cache = { at: 0, hits: [], soft: [] };
const CACHE_TTL = 4000;

export function getCachedGate() {
  return { ..._cache, fresh: Date.now() - _cache.at < CACHE_TTL };
}

async function collectLinux() {
  // Упрощённый скан на Linux: ps + bлacklist по имени процесса (без DLL).
  const hits = [];
  try {
    const r = spawnSync("ps", ["axww", "-o", "comm="], { encoding: "utf8", windowsHide: true });
    const procs = (r.stdout || "").split(/\r?\n/).map((s) => s.trim().toLowerCase().split("/").pop()).filter(Boolean);
    const names = new Set([
      "x64dbg", "x32dbg", "ollydbg", "gdb", "lldb", "ida", "ida64", "ghidra",
      "radare2", "cutter", "cheatengine", "frida", "wireshark", "tcpdump",
      "dnspy", "de4dot", "ilspy", "processhacker", "frpc", "proxychains",
    ]);
    for (const p of procs) {
      const b = p.replace(/\.(exe|bin)$/i, "");
      if (names.has(b)) hits.push("proc:" + b);
    }
  } catch {}
  return { hits, soft: [] };
}

async function collectCached() {
  const r = IS_WIN ? await runPowerShell() : await collectLinux();
  const { hits, soft } = parseOutput(r.stdout || "");
  _cache = { at: Date.now(), hits, soft };
  return { hits, soft };
}

export async function detectAnalysisTools() {
  const c = getCachedGate();
  if (c.fresh) return { blocked: c.hits.length > 0, hits: c.hits, soft: c.soft };
  const { hits, soft } = await collectCached();
  return { blocked: hits.length > 0, hits, soft };
}

let watchdogTimer = null;

export function startWatchdog(onHit, intervalMs = 2000) {
  stopWatchdog();
  let busy = false;
  watchdogTimer = setInterval(async () => {
    if (busy) return;
    busy = true;
    try {
      const gate = await detectAnalysisTools();
      if (gate.blocked) {
        stopWatchdog();
        onHit(gate.hits);
      }
    } catch {}
    finally { busy = false; }
  }, intervalMs);
  if (watchdogTimer.unref) watchdogTimer.unref();
}

export function stopWatchdog() {
  if (watchdogTimer) {
    clearInterval(watchdogTimer);
    watchdogTimer = null;
  }
}

export function gateSummary(hits) {
  const names = (hits || [])
    .map((h) => h.replace(/^(proc|win|cmd|dbg|vm|mac|~~):/, ""))
    .map((h) => (h.length > 60 ? h.slice(0, 57) + "..." : h));
  return [...new Set(names)].join(", ");
}

export const BLOCKED_PROCESS_NAMES = [];

export function gateVmInfo(soft) {
  const names = (soft || []).map((h) => h.replace(/^(vm|mac|~~):/, ""));
  return [...new Set(names)].join(", ");
}